(() => {
  const ID = 'arrow-escape';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, board, hint, scoreEl, cells = [], moves = 0, score = 0, callbacks = {}, initialized = false, finished = false;
  const icons = ['↑','→','↓','←','↗','↘','↙','↖','→'];
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function reset() { cells = icons.map((arrow, index) => ({ arrow, index, turns: 0, path: index === 0 || index === 4 || index === 8 })); moves = 0; score = 0; finished = false; render(); }
  function render() { board.innerHTML = cells.map(cell => `<button type="button" class="arrow-cell ${cell.path ? 'is-path' : ''} ${cell.index === 8 ? 'is-exit' : ''}" data-arrow-cell="${cell.index}" aria-label="Стрелка ${cell.index + 1}">${cell.arrow}</button>`).join(''); scoreEl.textContent = score; }
  function turn(index) { if (finished) return; const cell = cells[index]; cell.turns = (cell.turns + 1) % 4; cell.arrow = ['↑','→','↓','←'][cell.turns]; moves += 1; score = Math.max(0, 1000 - moves * 35); hint.textContent = cell.index === 8 && cell.arrow === '→' ? 'Выход открыт!' : 'Построй стрелочную программу до выхода'; render(); haptic('light'); if (cells[0].arrow === '→' && cells[1].arrow === '→' && cells[2].arrow === '↓' && cells[5].arrow === '↓' && cells[8].arrow === '→') finish(); }
  function finish() { finished = true; const previous = shell().getStats(ID), result = shell().saveResult(ID, score, { bestMoves: previous.bestMoves ? Math.min(previous.bestMoves, moves) : moves, lastResult: { score, moves } }), reward = Math.max(1, Math.floor(score / 150)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score, metadata: { transactionId: `game:${ID}:run:${Date.now()}`, moves } }); shell().emit('arrow_escape_finished', { gameId: ID, score, moves, reward }); shell().emit('game_finished', { gameId: ID, score, reward, moves, victory: true }); shell().ResultScreen.show(screen.querySelector('[data-arrow-result]'), { score, bestScore: result.bestScore, reward, newRecord: result.newRecord, title: 'Путь<br>найден!', details: { moves, arrows: '6 / 6' } }); screen.querySelector('[data-arrow-result]').hidden = false; }
  function start() { reset(); screen.querySelector('[data-arrow-start]').hidden = true; screen.querySelector('[data-arrow-result]').hidden = true; shell().emit('arrow_escape_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); haptic('light'); }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-arrow-start]').hidden = false; screen.querySelector('[data-arrow-result]').hidden = true; const stats = shell().getStats(ID); screen.querySelector('[data-arrow-menu-best]').textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); reset(); try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function init() { if (initialized) return; initialized = true; screen = document.getElementById('arrowEscapeScreen'); screen.innerHTML = `<div class="arrow-escape-inner"><header class="arrow-escape-hud"><button class="icon-button" data-arrow-close aria-label="На главную">×</button><div class="arrow-escape-brand"><small>TELEPLAY · ЛОГИКА</small><b>Arrow Escape</b></div><div class="arrow-escape-stat"><small>СЧЁТ</small><b data-arrow-score>0</b></div><button class="icon-button" data-arrow-reset aria-label="Начать заново">↻</button></header><div class="arrow-board" data-arrow-board></div><p class="arrow-hint" data-arrow-hint>Поверни стрелки и построй путь к выходу</p></div><div class="start-panel" data-arrow-start><span class="panel-kicker">TELEPLAY · ЛОГИКА</span><h2>Arrow<br>Escape</h2><p>Строй визуальную программу.<br>Освободи все стрелки.</p><button class="play-button large" data-arrow-start-button>Начать задачу</button><div class="record">Лучший результат: <b data-arrow-menu-best>0</b></div></div><div class="start-panel result-panel" data-arrow-result hidden><span class="panel-kicker" data-result="kicker">МАРШРУТ ОТКРЫТ</span><h2 data-result="title">Путь<br>найден!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Ходы <b data-result="moves">0</b></span><span>Стрелки <b data-result="arrows">0 / 6</b></span></div><button class="play-button large" data-arrow-replay>Новый маршрут</button><button class="text-button" data-arrow-home>На главную</button></div>`; board = screen.querySelector('[data-arrow-board]'); hint = screen.querySelector('[data-arrow-hint]'); scoreEl = screen.querySelector('[data-arrow-score]'); board.addEventListener('click', event => { const cell = event.target.closest('[data-arrow-cell]'); if (cell) turn(Number(cell.dataset.arrowCell)); }); screen.querySelector('[data-arrow-start-button]').addEventListener('click', start); screen.querySelector('[data-arrow-replay]').addEventListener('click', start); screen.querySelector('[data-arrow-home]').addEventListener('click', close); screen.querySelector('[data-arrow-close]').addEventListener('click', close); screen.querySelector('[data-arrow-reset]').addEventListener('click', start); reset(); }
  window.ArrowEscapeGame = { init, open, hide, close, start, restart: start, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
